onMounted(async()=>{if(!s.project)s.newProject();await nextTick();if(!s.config.editorPrefs?.zoomVersion)fitCanvas();else if(viewport.value){viewport.value.scrollLeft=s.config.editorPrefs?.scrollLeft||0;viewport.value.scrollTop=s.config.editorPrefs?.scrollTop||0;}sizeObserver=new ResizeObserver(()=>{});if(viewport.value)sizeObserver.observe(viewport.value);undoKey=e=>{if(s.tab==='comic'&&e.key==='Escape'&&!document.querySelector('.modal-backdrop')){e.preventDefault();clearSelection();return;}if(s.tab!=='comic'||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();s.action(()=>s.saveProject());}if(e.key==='Delete'&&object.value)remove();};window.addEventListener('keydown',undoKey);});
