function point(e){const pt=svg.value.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;return pt.matrixTransform(svg.value.getScreenCTM().inverse());}
function makePanel(points){return {id:crypto.randomUUID(),kind:'panel',name:`${s.t('分镜','Panel')} ${panels.value.length+1}`,points,fill:'#f6f5fa',border:'#242633',borderWidth:4,image:null,imageId:null,imageScale:1,imageX:0,imageY:0,rotation:0,visible:true};}
