function addDecoration(kind,preset={},at){checkpoint();const count=decorations.value.filter(o=>o.kind===kind).length+1,names={text:'文本',bubble:'对白',sticker:'贴纸'},w=kind==='sticker'?180:kind==='text'&&preset.vertical?100:320,h=kind==='sticker'?180:kind==='text'&&preset.vertical?360:150;
 const el=viewport.value,rect=el?.getBoundingClientRect();let center={x:page.value.width/2,y:page.value.height/2};if(rect&&svg.value){center=point({clientX:rect.left+rect.width/2,clientY:rect.top+rect.height/2});}
 const o={...preset,id:crypto.randomUUID(),kind,name:`${names[kind]} ${count}`,x:at?.x??Math.max(0,Math.min(page.value.width-w,center.x-w/2)),y:at?.y??Math.max(0,Math.min(page.value.height-h,center.y-h/2)),w,h,text:preset.text??(kind==='bubble'?'在这里输入对白':kind==='text'?'故事从这里开始':''),fontSize:preset.fontSize||(kind==='sticker'?90:36),color:preset.color||'#242633',fill:preset.fill||(kind==='bubble'?'#ffffff':'transparent'),border:'#242633',borderWidth:preset.borderWidth??(kind==='bubble'?3:0),rotation:0,visible:true};page.value.objects.push(o);selected.value=o.id;tool.value='select';}
function applyDecoration(preset){const choice=picker.value;if(choice.editId){const o=page.value.objects.find(o=>o.id===choice.editId);if(o){checkpoint();const keys=choice.kind==='sticker'?['presetId','image']:choice.kind==='bubble'?['shape','tailEnabled','tailAngle','tailLength','tailWidth','text','vertical','fontFamily','fontWeight','fontStyle','textDecoration','textAlign']:['presetId','text','fill','color','borderWidth','fontSize','fontWeight','fontFamily','fontStyle','textDecoration','textAlign','vertical'];for(const key of keys)if(preset[key]!==undefined)o[key]=preset[key];if(choice.kind==='sticker')o.text='';}}else addDecoration(choice.kind,preset);picker.value=null;}
function editDecoration(){if(object.value)picker.value={kind:object.value.kind,editId:object.value.id,initial:clone(object.value)};}
