function corners(o){return rectPoints(o.x,o.y,o.w,o.h);}
function rotateObject(o){return `rotate(${o.rotation||0} ${o.x+o.w/2} ${o.y+o.h/2})`;}
function startTail(e,o){e.stopPropagation();checkpoint();drag={kind:'tail',id:o.id};svg.value.setPointerCapture(e.pointerId);}
function startRotation(e,o){e.stopPropagation();checkpoint();const p=point(e);drag={kind:'rotate',id:o.id,original:clone(o),angle:Math.atan2(p.y-o.y-o.h/2,p.x-o.x-o.w/2)*180/Math.PI};svg.value.setPointerCapture(e.pointerId);}
function saveViewport(){if(viewport.value)s.config.editorPrefs={...s.config.editorPrefs,scrollLeft:viewport.value.scrollLeft,scrollTop:viewport.value.scrollTop};}
async function setZoom(value,anchor){const el=viewport.value;if(!el||!svg.value)return;const r=el.getBoundingClientRect(),target=anchor||{clientX:r.left+el.clientWidth/2,clientY:r.top+el.clientHeight/2},pt=point(target);zoom.value=Math.max(10,Math.min(400,Math.round(value)));await nextTick();const q=svg.value.createSVGPoint();q.x=pt.x;q.y=pt.y;const pos=q.matrixTransform(svg.value.getScreenCTM());el.scrollLeft+=pos.x-target.clientX;el.scrollTop+=pos.y-target.clientY;saveViewport();}
function wheel(e){if(e.ctrlKey||e.metaKey){e.preventDefault();setZoom(zoom.value*Math.exp(-e.deltaY*.002),e);}else if(e.shiftKey){e.preventDefault();viewport.value.scrollLeft+=e.deltaY||e.deltaX;}}
