function selectObject(e,o){if(e.button!==0)return;if(tool.value==='select'&&o.kind==='bubble'&&(e.ctrlKey||e.metaKey)){e.stopPropagation();selectLayer(e,o);return;}if(tool.value==='select'){e.stopPropagation();checkpoint();selected.value=o.id;bubbleSelection.value=o.linkGroup?page.value.objects.filter(x=>x.linkGroup===o.linkGroup).map(x=>x.id):o.kind==='bubble'?[o.id]:[];drag={kind:'move',id:o.id,start:point(e),original:clone(o),linked:o.linkGroup?page.value.objects.filter(item=>item.linkGroup===o.linkGroup&&item.id!==o.id).map(item=>clone(item)):[]};svg.value.setPointerCapture(e.pointerId);}else if(tool.value==='eraser'&&o.kind==='stroke'){e.stopPropagation();checkpoint();page.value.objects=page.value.objects.filter(x=>x.id!==o.id);}}
function down(e){if(e.button!==0)return;const pt=point(e);svg.value.setPointerCapture(e.pointerId);if(['frame','overlay','cut'].includes(tool.value)){checkpoint();drag={kind:tool.value,start:pt,end:pt,panelId:selected.value};}else if(tool.value==='brush'||tool.value==='eraser'){checkpoint();const o={id:crypto.randomUUID(),kind:'stroke',name:s.t('笔画','Stroke'),points:[{x:pt.x,y:pt.y}],color:tool.value==='eraser'?page.value.background:brushColor.value,width:tool.value==='eraser'?brushSize.value*4:brushSize.value,visible:true};page.value.objects.push(o);drag={kind:'stroke',id:o.id};}else if(['bubble','text','sticker'].includes(tool.value))picker.value={kind:tool.value};else if(tool.value==='pan')drag={kind:'pan',start:{x:e.clientX,y:e.clientY},element:e.currentTarget.closest('.canvas-scroll'),scrollLeft:e.currentTarget.closest('.canvas-scroll').scrollLeft,scrollTop:e.currentTarget.closest('.canvas-scroll').scrollTop};else if(tool.value==='zoom')setZoom(zoom.value*1.25,e);else clearSelection();}
function move(e){if(!drag)return;if(!(e.buttons&1)){drag=null;dragVisual.value=null;return;}const pt=point(e);if(drag.kind==='move'){const o=page.value.objects.find(x=>x.id===drag.id);const dx=pt.x-drag.start.x,dy=pt.y-drag.start.y;if(o.kind==='panel')o.points=drag.original.points.map(p=>({x:p.x+dx,y:p.y+dy}));else if(o.kind==='stroke')o.points=drag.original.points.map(p=>({x:p.x+dx,y:p.y+dy}));else{o.x=drag.original.x+dx;o.y=drag.original.y+dy;}for(const original of drag.linked||[]){const linked=page.value.objects.find(item=>item.id===original.id);if(linked){linked.x=original.x+dx;linked.y=original.y+dy;}}}else if(drag.kind==='vertex'){const o=page.value.objects.find(x=>x.id===drag.id);if(e.shiftKey)o.points=scaleFromCorner(drag.original.points,drag.index,pt);else o.points[drag.index]={x:pt.x,y:pt.y};}else if(drag.kind==='resize'){const o=page.value.objects.find(x=>x.id===drag.id);Object.assign(o,resizeDecoration(drag.original,drag.index,pt,e.shiftKey));}else if(drag.kind==='tail'){Object.assign(page.value.objects.find(x=>x.id===drag.id),editTail(page.value.objects.find(x=>x.id===drag.id),pt));}else if(drag.kind==='rotate'){const o=page.value.objects.find(x=>x.id===drag.id);let angle=drag.original.rotation+Math.atan2(pt.y-o.y-o.h/2,pt.x-o.x-o.w/2)*180/Math.PI-drag.angle;o.rotation=Math.round(e.shiftKey?Math.round(angle/15)*15:angle);}else if(drag.kind==='canvas'){const resized=clone(drag.original);resizePage(resized,pt.x,pt.y,{keepRatio:!!page.value.keepCanvasRatio,scaleContents:!!page.value.scaleCanvasContents});Object.assign(page.value,resized);}else if(drag.kind==='stroke'){page.value.objects.find(x=>x.id===drag.id).points.push({x:pt.x,y:pt.y});}else if(drag.kind==='pan'){drag.element.scrollLeft=drag.scrollLeft-(e.clientX-drag.start.x);drag.element.scrollTop=drag.scrollTop-(e.clientY-drag.start.y);}else{drag.end=pt;dragVisual.value={...drag};}}
const dragVisual=ref(null);
function up(e){if(e&&svg.value?.hasPointerCapture(e.pointerId))svg.value.releasePointerCapture(e.pointerId);if(!drag)return;if(drag.kind==='frame'||drag.kind==='overlay'){const x=Math.min(drag.start.x,drag.end.x),y=Math.min(drag.start.y,drag.end.y),w=Math.abs(drag.end.x-drag.start.x),h=Math.abs(drag.end.y-drag.start.y);if(w>30&&h>30){const o=makePanel(rectPoints(x,y,w,h));page.value.objects.push(o);selected.value=o.id;}}else if(drag.kind==='cut'){const target=page.value.objects.find(o=>o.id===drag.panelId&&o.kind==='panel');if(target){const parts=splitPolygon(target.points,drag.start,drag.end);if(parts){target.points=parts[0];const copy={...clone(target),id:crypto.randomUUID(),points:parts[1],name:`${s.t('分镜','Panel')} ${panels.value.length+1}`};page.value.objects.push(copy);}else s.notify(s.t('切割线需要穿过选中的分镜','Draw the cut across the selected panel'));}else s.notify(s.t('先选择需要切割的分镜，再使用切割工具','Select a panel before splitting'));}drag=null;dragVisual.value=null;}
function vertex(e,o,index){e.stopPropagation();checkpoint();drag={kind:'vertex',id:o.id,index,original:clone(o)};svg.value.setPointerCapture(e.pointerId);}
function resize(e,o,index){e.stopPropagation();checkpoint();drag={kind:'resize',id:o.id,index,original:clone(o)};svg.value.setPointerCapture(e.pointerId);}
function resizeCanvas(e){e.stopPropagation();checkpoint();drag={kind:'canvas',original:clone(page.value)};svg.value.setPointerCapture(e.pointerId);}
function applyTemplate(){const apply=()=>{checkpoint();page.value.objects=page.value.objects.filter(o=>o.kind!=='panel');for(const points of templatePanels(template.value,page.value.width,page.value.height))page.value.objects.push(makePanel(points));selected.value='canvas';};if(panels.value.length)confirmAction.value={text:s.t('替换当前分镜布局？现有分镜中的图片会被移出画布，图片仍保留在画廊。','Replace this layout? Images remain in your gallery.'),run:apply};else apply();}
