function clearPage(){confirmAction.value={text:s.t('清空本页所有分镜与图层？可以使用撤销恢复。','Clear all layers on this page? You can undo.'),run:()=>{checkpoint();page.value.objects=[];selected.value='canvas';}};}
function deletePage(index=pageIndex.value){if(!Number.isInteger(index))index=pageIndex.value;if(s.project.pages.length===1){s.notify(s.t('项目至少需要保留一页','Keep at least one page'));return;}const target=s.project.pages[index];if(!target)return;pageListOpen.value=false;confirmAction.value={text:'删除漫画页“'+target.name+'”？可用撤销恢复。',run:()=>{const i=s.project.pages.findIndex(p=>p.id===target.id);if(i<0)return;checkpoint();s.project.pages.splice(i,1);pageIndex.value=Math.max(0,Math.min(pageIndex.value-(i<pageIndex.value?1:0),s.project.pages.length-1));selected.value='canvas';}};}
function reorderSelection(direction,scope='group'){const ids=bubbleSelection.value.length?bubbleSelection.value:object.value?[object.value.id]:[];if(!canMoveLayerSelection(page.value.objects,ids,direction,scope))return;checkpoint();page.value.objects=moveLayerSelection(page.value.objects,ids,direction,scope);bubbleMenu.value=null;}
function canReorder(direction,scope='group'){return canMoveLayerSelection(page.value.objects,bubbleSelection.value.length?bubbleSelection.value:object.value?[object.value.id]:[],direction,scope);}
function updateGeometry(field,value){if(!object.value||!Number.isFinite(value))return;if(field==='w'||field==='h')value=Math.max(1,Math.min(32768,value));const b=selectedBounds.value;if(object.value.kind==='panel'){object.value.points=object.value.points.map(p=>({x:field==='x'?p.x+value-b.x:field==='w'?b.x+(p.x-b.x)*(value/b.w):p.x,y:field==='y'?p.y+value-b.y:field==='h'?b.y+(p.y-b.y)*(value/b.h):p.y}));}else object.value[field]=value;}
function changePanelSides(value){if(!panel.value||!Number.isFinite(Number(value)))return;const count=Math.max(3,Math.min(32,Math.round(Number(value))));if(count===panel.value.points.length)return;checkpoint();panel.value.points=polygonWithSides(panel.value.points,count);}
async function placeImage(item){if(!panel.value)return;checkpoint();setPanelImage(panel.value,item);panel.value.imageScale=1;panel.value.imageX=0;panel.value.imageY=0;galleryOpen.value=false;}
async function uploadImage(e){const results=await s.action(()=>s.importImages([...e.target.files],{select:false}));if(results?.length)await placeImage(results[0]);e.target.value='';}
function generatePanel(target=panel.value){if(!target||target.kind!=='panel')return;selected.value=target.id;ensurePanelGeneration(target,s.gallery,s.config.activeProfile);panelGenerator.value={projectId:s.project.id,pageId:page.value.id,panelId:target.id,mode:panelEditingMode(target,s.gallery)||'generate'};panelGroup.value=null;}
