const generatingPanel=computed(()=>panelGenerator.value?.projectId===s.project?.id?s.project.pages.find(pg=>pg.id===panelGenerator.value.pageId)?.objects.find(o=>o.id===panelGenerator.value.panelId):null);
watch(()=>generatingPanel.value?.imageMetadataDeleted,deleted=>{if(deleted)panelGenerator.value=null;});
const candidates=computed(()=>generatingPanel.value?panelCandidates(generatingPanel.value,panelGenerator.value,s.gallery):[]);
function chooseCandidate(item){if(!generatingPanel.value)return;checkpoint();setPanelImage(generatingPanel.value,item);panelGenerator.value.mode=imageEditingMode(item)||panelGenerator.value.mode;}
function canvasDoubleClick(){drag=null;dragVisual.value=null;if(tool.value==='select'&&object.value)doubleClickObject(object.value);}
function doubleClickObject(o){drag=null;dragVisual.value=null;const owner=layerSourcePanel(o,page.value);if(owner&&panelEditingMode(owner,s.gallery)){generatePanel(owner);return;}if(o.cutout){refineCutout(o);return;}if(['text','bubble','sticker'].includes(o.kind)){selected.value=o.id;editDecoration();}}

watch(()=>s.jobs.map(j=>j.status).join(','),()=>{if(!panelGroup.value||!panelGenerator.value)return;const jobs=s.jobs.filter(j=>j.groupId===panelGroup.value);if(jobs.length&&jobs.every(j=>['complete','error','cancelled','interrupted'].includes(j.status))){panelGroup.value=null;}});
function scaleCutout(value){const o=object.value;if(!o?.cutout)return;const cx=o.x+o.w/2,cy=o.y+o.h/2;o.cutoutBaseW||=o.w;o.cutoutBaseH||=o.h;o.w=o.cutoutBaseW*value;o.h=o.cutoutBaseH*value;o.x=cx-o.w/2;o.y=cy-o.h/2;}
function groupIds(o){return o.linkGroup?page.value.objects.filter(x=>x.linkGroup===o.linkGroup).map(x=>x.id):[o.id];}
function selectLayer(e,o){if(skipLayerClick)return;tool.value='select';const ids=chooseLayerIds(bubbleSelection.value,o.id,{toggle:e.ctrlKey||e.metaKey,group:groupIds(o)});bubbleSelection.value=ids;selected.value=ids.at(-1)||'canvas';bubbleMenu.value=null;}
function toggleLayer(o){const ids=chooseLayerIds(bubbleSelection.value,o.id,{toggle:true});bubbleSelection.value=ids;selected.value=ids.at(-1)||'canvas';}
function openLayerContext(e,o){bubbleSelection.value=contextLayerIds(bubbleSelection.value,o?.id,o?groupIds(o):[]);selected.value=bubbleSelection.value.at(-1)||'canvas';bubbleMenu.value={x:Math.max(8,Math.min(e.clientX,window.innerWidth-190)),y:Math.max(8,Math.min(e.clientY,window.innerHeight-(selectedBubbles.value.length>=2?210:150)))};}
const selectedBubbles=computed(()=>page.value?.objects.filter(o=>['bubble','text'].includes(o.kind)&&bubbleSelection.value.includes(o.id))||[]);
const canUnlink=computed(()=>selectedBubbles.value.some(o=>o.linkGroup));

function linkBubbles(){const items=selectedBubbles.value;if(items.length<2)return;checkpoint();const id=crypto.randomUUID();const previous=new Set(items.map(o=>o.linkGroup).filter(Boolean));for(const o of page.value.objects)if(items.includes(o)||previous.has(o.linkGroup)){o.linkGroup=id;if(o.kind==='bubble')o.rotation=0;}(page.value.bubbleLinks||(page.value.bubbleLinks={}))[id]={strength:.55};bubbleMenu.value=null;}
function unlinkBubbles(){checkpoint();const groups=new Set(selectedBubbles.value.map(o=>o.linkGroup).filter(Boolean));for(const o of page.value.objects)if(groups.has(o.linkGroup)||selectedBubbles.value.includes(o))delete o.linkGroup;bubbleMenu.value=null;}
function deleteSelectedLayers(){const ids=new Set(bubbleSelection.value.length?bubbleSelection.value:object.value?[object.value.id]:[]);if(!ids.size)return;checkpoint();page.value.objects=page.value.objects.filter(o=>!ids.has(o.id));clearSelection();}

function editPageSize(field,value){if(!Number.isFinite(value))return;checkpoint();resizePage(page.value,field==='width'?value:page.value.width,field==='height'?value:page.value.height,{changed:field,keepRatio:!!page.value.keepCanvasRatio,scaleContents:!!page.value.scaleCanvasContents});}
watch(selected,async id=>{const o=object.value;if(o?.cutout)page.value.cutoutsCollapsed=false;else if(o?.kind==='panel')page.value.panelsCollapsed=false;else if(o){page.value.layerGroupCollapsed||={};page.value.layerGroupCollapsed[o.kind]=false;}await nextTick();const row=document.querySelector(`[data-layer-id="${id}"]`);row?.scrollIntoView({block:'nearest',inline:'nearest'});});
function removeFromGroup(group){const o=object.value,match=o&&(group==='panels'?o.kind==='panel':group==='cutouts'?o.cutout:o.kind===group&&!o.cutout);if(match)remove();else s.notify('请先选中这个图层组里的一个图层，再点击减号。');}
function quickCutout(){const p=panel.value||page.value.objects.find(o=>o.kind==='panel'&&o.image);if(!p?.image){s.notify('先给分镜添加图片，再使用智能抠图。');return;}const source=s.gallery.find(g=>g.id===p.imageId)||{id:p.imageId,url:p.image};cutoutRefine.value={add:true,panel:p,source};layerMenu.value=null;}
async function importCutout(e){const images=await s.action(()=>s.importImages([...e.target.files],{select:false}));for(const item of images||[]){const img=new Image();img.src=item.url;await img.decode();item.params={...item.params,width:img.naturalWidth,height:img.naturalHeight};const source={id:null,imageId:item.id,points:rectPoints(page.value.width*.25,page.value.height*.2,Math.min(page.value.width*.5,img.naturalWidth),Math.min(page.value.width*.5,img.naturalWidth)*img.naturalHeight/img.naturalWidth)};addCutout(item,source);}e.target.value='';layerMenu.value=null;}
function alignCutout(){const layer=object.value,p=layerSourcePanel(layer,page.value);if(!p){s.notify('这个抠图没有关联分镜，请先将原图放入分镜。','error');return;}const next=alignedCutout(layer,p);if(next){checkpoint();Object.assign(layer,next);s.notify('已对齐分镜原图，可撤销');}}
function refineCutout(layer=object.value){const source=cutoutSourceImage(layer,page.value,s.gallery);if(source)cutoutRefine.value={object:layer,source};else if(layer?.image)cutoutRefine.value={object:layer,source:{id:layer.imageId,url:layer.image,title:layer.name}};}
function finishCutoutRefine(item){if(cutoutRefine.value.add){addCutout(item,cutoutRefine.value.panel);cutoutRefine.value=null;return;}checkpoint();cutoutRefine.value.object.image=item.url;cutoutRefine.value.object.imageId=item.id;cutoutRefine.value=null;}
function openImageEditor(o){if(o.kind==='panel'&&o.image){checkpoint();selected.value=o.id;tool.value='select';panelImageEditor.value=o;}}
function addCutout(item,sourceOverride){const source=sourceOverride||panelImageEditor.value,b=bounds(source.points),sourceRatio=(item.params?.width||1024)/(item.params?.height||768),cover=Math.max(b.w/(item.params?.width||1024),b.h/(item.params?.height||768)),w=(item.params?.width||1024)*cover*(source.imageScale||1),h=w/sourceRatio;checkpoint();const o={id:crypto.randomUUID(),kind:'sticker',name:source.name+' · 破框主体',image:item.url,imageId:item.id,x:b.x+(b.w-w)/2+(source.imageX||0),y:b.y+(b.h-h)/2+(source.imageY||0),w,h,color:'#242633',rotation:source.imageRotation||0,visible:true,opacity:1,cutout:true,outsideOnly:true,groupId:'cutouts',cutoutBaseW:w,cutoutBaseH:h,sourceImageId:item.sourceImageId||source.imageId,sourcePanelId:source.id,sourceImage:source.image};page.value.objects.push(o);selected.value=o.id;panelImageEditor.value=null;s.notify('已添加独立破框图层，拖动四角放大、移动到分镜边缘即可。');}
async function embedImages(project){await embedProjectFonts(project);for(const pg of project.pages){if(pg.backgroundImage?.startsWith('/api/'))pg.backgroundImage=await imageData(pg.backgroundImage);for(const o of pg.objects){if(o.kind==='panel'&&o.image)ensurePanelGeneration(o,s.gallery,s.config.activeProfile);if(o.image?.startsWith('/api/'))o.image=await imageData(o.image);if(o.sourceImage?.startsWith('/api/'))o.sourceImage=await imageData(o.sourceImage);}}return project;}
async function imageData(url){const blob=await(await fetch(url)).blob();return new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(blob);});}
async function exportProject(){await s.action(async()=>{const data=await embedImages(clone(s.project));await s.exportFile(s.project.name+'.ruoshui.json',new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));s.notify(s.t('项目已导出，包含图片，可以继续编辑','Project exported with embedded images'));});}
async function importProject(e){await s.action(async()=>{const data=JSON.parse(await e.target.files[0].text());await restoreProjectFonts(data);data.id=crypto.randomUUID();for(const pg of data.pages||[])for(const o of pg.objects||[])o.id=o.id||crypto.randomUUID();const {api}=await import('../store');s.project=await api('projects/save',data);pageIndex.value=0;selected.value='canvas';});e.target.value='';}
async function exportPng(){exporting.value=true;await s.action(async()=>{await nextTick();const exportPage={width:page.value.width,height:page.value.height,index:pageIndex.value,name:s.project.name};const fontPage=JSON.parse(JSON.stringify(page.value)),clone=svg.value.cloneNode(true);await embedSvgFonts(clone,fontPage);clone.querySelectorAll('.editor-only').forEach(e=>e.remove());clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width',String(exportPage.width));clone.setAttribute('height',String(exportPage.height));clone.removeAttribute('style');for(const img of clone.querySelectorAll('image')){const href=img.getAttribute('href');if(href?.startsWith('/api/'))img.setAttribute('href',await imageData(href));}const xml=new XMLSerializer().serializeToString(clone);const blob=new Blob([xml],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error(s.t('漫画导出失败，请检查图片','Image export failed')));img.src=url;});const canvas=document.createElement('canvas');canvas.width=exportPage.width;canvas.height=exportPage.height;canvas.getContext('2d').drawImage(img,0,0);URL.revokeObjectURL(url);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const saved=await s.exportFile(`${exportPage.name}-${exportPage.index+1}.png`,png,{kind:'comic',projectName:exportPage.name});if(saved===false)return;s.notify(s.t('漫画页已导出为 PNG','Comic page exported as PNG'));});exporting.value=false;}
function pointsString(points){return points.map(p=>`${p.x},${p.y}`).join(' ');}
</script>
<template><div v-if="page" class="comic-workspace"><div class="comic-header card"><div class="button-row"><input v-if="renamingPage" v-model="page.name" aria-label="漫画页名称" class="page-name-input" @keydown.enter="renamingPage=false" @blur="renamingPage=false" autofocus/><div v-else class="page-picker"><button class="page-picker-trigger" aria-haspopup="listbox" :aria-expanded="pageListOpen" @click="pageListOpen=!pageListOpen">{{pageIndex+1}} · {{page.name}}<ChevronDown :size="15"/></button><template v-if="pageListOpen"><div class="page-picker-dismiss" @click="pageListOpen=false"/><div class="page-picker-list" role="listbox" aria-label="漫画页列表"><div v-for="(pg,i) in s.project.pages" :key="pg.id" :class="{active:pageIndex===i}"><button role="option" :aria-selected="pageIndex===i" :title="pg.name" @click="pageIndex=i;pageListOpen=false;selected='canvas'">{{i+1}} · {{pg.name}}</button><button class="icon-button danger" :title="'删除漫画页：'+pg.name" :aria-label="'删除漫画页：'+pg.name" :disabled="s.project.pages.length===1" @click="deletePage(i)"><Trash2 :size="15"/></button></div></div></template></div><button class="icon-button" title="重命名当前漫画页" aria-label="重命名当前漫画页" @click="renamingPage=!renamingPage"><Pencil :size="15"/></button><button class="icon-button danger" title="删除当前漫画页" aria-label="删除当前漫画页" :disabled="s.project.pages.length===1" @click="deletePage()"><Trash2 :size="15"/></button><button class="quiet" @click="checkpoint();s.project.pages.push(s.newPage());pageIndex=s.project.pages.length-1;selected='canvas'"><FilePlus2 :size="16"/>{{s.t('新建画布','Add page')}}</button><button class="quiet" @click="projectDialog=true"><FolderOpen :size="16"/>{{s.t('打开项目','Open project')}}</button></div><div class="button-row"><button class="secondary" @click="projectInput.click()"><Upload :size="15"/>{{s.t('导入项目','Import project')}}</button><button class="secondary" @click="exportProject">{{s.t('导出项目','Export project')}}</button><button class="primary" @click="exportPng" :disabled="exporting"><Download :size="16"/>{{exporting?s.t('导出中…','Exporting…'):s.t('导出漫画 PNG','Export PNG')}}</button><button class="secondary" @click="s.action(()=>s.openFolder('comic-exports',s.project.name))"><FolderOpen :size="16"/>{{s.t('打开漫画文件夹','Open comic folder')}}</button></div></div>
 <div class="comic-grid" v-resize-panels="{key:'comic',config:s.config,min:[100,260,220],labels:['调整编辑工具宽度','调整图层与属性宽度']}"><aside class="comic-tools card"><div class="tool-section"><strong>{{s.t('画布与分镜','PAGE & PANELS')}}</strong><button @click="clearPage">{{s.t('清空画布','Clear page')}}</button><button @click="deletePage">{{s.t('删除画布','Delete page')}}</button><button @click="addPanel"><Plus :size="15"/>{{s.t('新建分镜','Add panel')}}</button><select v-model="template"><option value="story">{{s.t('故事四格','Story · 4 panels')}}</option><option value="four">{{s.t('均匀四格','Grid · 4 panels')}}</option><option value="six">{{s.t('均匀六格','Grid · 6 panels')}}</option><option value="strip">{{s.t('纵向三格','Strip · 3 panels')}}</option><option value="hero">{{s.t('主视觉三格','Hero · 3 panels')}}</option><option value="single">{{s.t('整页单格','Full page')}}</option></select><button class="template-button" @click="applyTemplate">{{s.t('应用分镜模板','Apply layout')}}</button></div><div class="tool-section"><button @click="undo" :disabled="!undoCount"><Undo2 :size="17"/>{{s.t('撤销','Undo')}}</button><button @click="redo" :disabled="!redoCount"><Redo2 :size="17"/>{{s.t('重做','Redo')}}</button></div><div class="tool-section"><strong>{{s.t('编辑工具','TOOLS')}}</strong><button v-for="item in tools" :class="{active:tool===item.id}" @click="chooseTool(item.id)"><component :is="item.icon" :size="17"/>{{item.name}}</button></div></aside>
 <section class="canvas-zone"><div class="canvas-toolbar"><span>{{s.t('画布','Page')}} {{pageIndex+1}}<span class="muted"> · {{page.width}} × {{page.height}} px</span></span><div><button class="quiet" @click="fitCanvas">适合窗口</button><button class="icon-button" aria-label="缩小画布" @click="setZoom(zoom/1.2)">−</button><span>{{zoom}}%</span><button class="icon-button" aria-label="放大画布" @click="setZoom(zoom*1.2)">＋</button></div></div><div ref="viewport" class="canvas-scroll" aria-label="漫画画布视图" tabindex="0" @wheel="wheel" @scroll="saveViewport"><div class="canvas-stage" :style="{width:(page.width*zoom/100+80)+'px',height:(page.height*zoom/100+80)+'px'}"><svg ref="svg" v-brush-cursor="{size:brushSize*(tool==='eraser'?4:1)*zoom/100,enabled:tool==='brush'||tool==='eraser'}" class="comic-canvas" :viewBox="`0 0 ${page.width} ${page.height}`" :style="{width:(page.width*zoom/100)+'px',height:(page.height*zoom/100)+'px'}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @dblclick="canvasDoubleClick" :data-tool="tool"><ComicArtwork :page="page" editable @select="selectObject" @edit="doubleClickObject" @context="openLayerContext"/>
  <g v-if="object&&object.kind==='panel'" class="editor-only"><polygon :points="pointsString(object.points)" fill="none" stroke="#8060df" stroke-width="3" stroke-dasharray="10 5"/><circle v-for="(pt,i) in object.points" :cx="pt.x" :cy="pt.y" r="10" fill="white" stroke="#8060df" stroke-width="3" class="resize-handle" @pointerdown="vertex($event,object,i)"/></g><g v-else-if="object&&object.kind!=='stroke'" class="editor-only" :transform="rotateObject(object)"><rect :x="object.x" :y="object.y" :width="object.w" :height="object.h" fill="none" stroke="#8060df" stroke-width="2" vector-effect="non-scaling-stroke" stroke-dasharray="6 4"/><circle v-for="(pt,i) in corners(object)" :cx="pt.x" :cy="pt.y" :r="6/(zoom/100)" fill="white" stroke="#8060df" stroke-width="2" vector-effect="non-scaling-stroke" class="resize-handle" @pointerdown="resize($event,object,i)"/><line :x1="object.x+object.w/2" :y1="object.y" :x2="object.x+object.w/2" :y2="object.y-28/(zoom/100)" stroke="#8060df" vector-effect="non-scaling-stroke"/><circle :cx="object.x+object.w/2" :cy="object.y-28/(zoom/100)" :r="6/(zoom/100)" fill="#efe8ff" stroke="#8060df" stroke-width="2" vector-effect="non-scaling-stroke" class="rotation-handle" @pointerdown="startRotation($event,object)"/><template v-if="object.kind==='bubble'&&object.tailEnabled!==false"><line :x1="object.x+object.w/2" :y1="object.y+object.h/2" :x2="object.x+bubbleTail(object).x" :y2="object.y+bubbleTail(object).y" stroke="#dc851c" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/><circle :cx="object.x+bubbleTail(object).x" :cy="object.y+bubbleTail(object).y" :r="8/(zoom/100)" fill="#fff5d8" stroke="#d5801c" stroke-width="2" vector-effect="non-scaling-stroke" class="tail-handle" @pointerdown="startTail($event,object)"/></template></g><rect v-if="selected==='canvas'" class="editor-only" :x="page.width-20" :y="page.height-20" width="18" height="18" fill="#8060df" @pointerdown="resizeCanvas"/>
  <g v-if="dragVisual" class="editor-only"><line v-if="dragVisual.kind==='cut'" :x1="dragVisual.start.x" :y1="dragVisual.start.y" :x2="dragVisual.end.x" :y2="dragVisual.end.y" stroke="#8060df" stroke-width="5" stroke-dasharray="12 7"/><rect v-else :x="Math.min(dragVisual.start.x,dragVisual.end.x)" :y="Math.min(dragVisual.start.y,dragVisual.end.y)" :width="Math.abs(dragVisual.end.x-dragVisual.start.x)" :height="Math.abs(dragVisual.end.y-dragVisual.start.y)" fill="#8060df22" stroke="#8060df" stroke-width="3"/></g>
 </svg></div></div><div class="canvas-help">{{tool==='cut'?s.t('选中分镜后，拖一条穿过分镜的切割线。','Select a panel, then drag a cut across it.'):tool==='frame'?s.t('在画布上拖动，画出新的分镜。','Drag on the page to draw a panel.'):s.t('Ctrl＋滚轮缩放 · Shift＋滚轮横移 · Shift＋拖角等比缩放','Drag corners to reshape · Shift + drag to scale proportionally · Ctrl+Z undo')}}</div></section>
 <aside class="comic-properties" v-resize-panels="{key:'comic-properties',axis:'rows',config:s.config,min:[140,220],labels:['调整图层与属性高度']}"><section class="card layers-panel"><div class="card-heading"><div><Layers :size="16"/><strong>{{s.t('图层','Layers')}}</strong></div><span>{{page.objects.length}}</span></div><div ref="layerPane" class="layers-content" @pointerdown="layerSelectDown" @pointermove="layerSelectMove" @pointerup="layerSelectUp" @pointercancel="layerSelectUp" @contextmenu.self.prevent="openLayerContext($event)"><div v-if="layerMarquee" class="layer-selection-box" :style="{left:layerMarquee.left+'px',top:layerMarquee.top+'px',width:layerMarquee.width+'px',height:layerMarquee.height+'px'}"/><div :class="['layer-row',{selected:selected==='canvas'}]" @click="clearSelection"><Square :size="15"/><input v-if="renamingLayer==='canvas'" v-model="layerNameDraft" data-rename-layer="canvas" aria-label="重命名主画布" @click.stop @keydown.enter.stop.prevent="saveLayerName({id:'canvas'})" @keydown.esc.stop="renamingLayer=null" @blur="saveLayerName({id:'canvas'})"/><span v-else>{{page.canvasName||s.t('主画布','Page background')}}</span><button class="icon-button layer-rename" title="重命名主画布" @click.stop="renameLayer({id:'canvas',name:page.canvasName||'主画布'})"><Pencil :size="13"/></button></div><div class="layer-group-heading"><button class="group-title" @click="page.panelsCollapsed=!page.panelsCollapsed"><ChevronDown :size="14" :class="{folded:page.panelsCollapsed}"/>分镜</button><button class="icon-button" aria-label="新建分镜图层" title="新建分镜" @click="addPanel"><Plus :size="14"/></button><button class="icon-button" aria-label="删除选中的分镜图层" title="删除选中的分镜" @click="removeFromGroup('panels')">−</button></div><template v-if="!page.panelsCollapsed"><div v-for="o in panels" :data-layer-id="o.id" :class="['layer-row',{selected:highlighted(o)}]" @click="selectLayer($event,o)" @contextmenu.stop.prevent="openLayerContext($event,o)"><span v-if="bubbleSelection.includes(o.id)" class="layer-selection-check">✓</span><span class="layer-number">{{panels.indexOf(o)+1}}</span><input v-if="renamingLayer===o.id" v-model="layerNameDraft" :data-rename-layer="o.id" aria-label="重命名图层" maxlength="120" @click.stop @keydown.enter.stop.prevent="saveLayerName(o)" @keydown.esc.stop="renamingLayer=null" @blur="saveLayerName(o)"/><span v-else>{{o.name}}</span><button class="icon-button layer-rename" :title="'重命名 '+o.name" :aria-label="'重命名 '+o.name" @click.stop="renameLayer(o)"><Pencil :size="13"/></button><Link v-if="o.linkGroup" :size="13" class="bubble-chain"/><button class="icon-button" @click.stop="checkpoint();o.visible=o.visible===false"><EyeOff v-if="o.visible===false" :size="13"/><Eye v-else :size="13"/></button></div></template><div class="cutout-group-heading layer-group-heading"><button @click="selected='cutout-group';page.cutoutsCollapsed=!page.cutoutsCollapsed" :aria-expanded="!page.cutoutsCollapsed"><ChevronDown :size="15" :style="{transform:page.cutoutsCollapsed?'rotate(-90deg)':''}"/><strong>抠图图层组</strong><small>{{cutouts.length}}</small></button><div class="layer-add-menu"><button class="icon-button" aria-label="添加抠图图层" @click="layerMenu=layerMenu==='cutouts'?null:'cutouts'"><Plus :size="14"/></button><div v-if="layerMenu==='cutouts'" class="layer-menu"><button @click="quickCutout">从分镜智能抠图</button><button @click="cutoutInput.click();layerMenu=null">导入透明图片</button></div></div><button class="icon-button" aria-label="删除选中的抠图图层" @click="removeFromGroup('cutouts')">−</button><button class="icon-button" title="显示或隐藏整个抠图图层组" @click="page.cutoutsVisible=page.cutoutsVisible===false"><EyeOff v-if="page.cutoutsVisible===false" :size="14"/><Eye v-else :size="14"/></button></div><template v-if="!page.cutoutsCollapsed"><div v-for="o in cutouts" :data-layer-id="o.id" :class="['layer-row','cutout-layer-row',{selected:highlighted(o)}]" @click="selectLayer($event,o)" @contextmenu.stop.prevent="openLayerContext($event,o)"><span v-if="bubbleSelection.includes(o.id)" class="layer-selection-check">✓</span><Sticker :size="15"/><input v-if="renamingLayer===o.id" v-model="layerNameDraft" :data-rename-layer="o.id" aria-label="重命名图层" maxlength="120" @click.stop @keydown.enter.stop.prevent="saveLayerName(o)" @keydown.esc.stop="renamingLayer=null" @blur="saveLayerName(o)"/><span v-else>{{o.name}}</span><button class="icon-button layer-rename" :title="'重命名 '+o.name" :aria-label="'重命名 '+o.name" @click.stop="renameLayer(o)"><Pencil :size="13"/></button><Link v-if="o.linkGroup" :size="13" class="bubble-chain"/><button class="icon-button" @click.stop="o.visible=o.visible===false"><EyeOff v-if="o.visible===false" :size="13"/><Eye v-else :size="13"/></button></div></template><template v-for="group in decorationGroups" :key="group.id"><div class="layer-group-heading"><button class="group-title" :aria-expanded="!page.layerGroupCollapsed?.[group.id]" @click="page.layerGroupCollapsed||={};page.layerGroupCollapsed[group.id]=!page.layerGroupCollapsed[group.id]"><ChevronDown :size="14" :class="{folded:page.layerGroupCollapsed?.[group.id]}"/>{{group.name}}<small>{{group.objects.length}}</small></button><button v-if="group.id!=='stroke'" class="icon-button" :aria-label="'添加'+group.name+'图层'" @click="chooseTool(group.id)"><Plus :size="14"/></button><button class="icon-button" :aria-label="'删除选中的'+group.name+'图层'" @click="removeFromGroup(group.id)">−</button></div><template v-if="!page.layerGroupCollapsed?.[group.id]"><div v-for="o in group.objects" :key="o.id" :data-layer-id="o.id" :class="['layer-row',{selected:highlighted(o)}]" @click="selectLayer($event,o)" @contextmenu.stop.prevent="openLayerContext($event,o)"><button v-if="bubbleSelection.includes(o.id)" class="layer-selection-check" :aria-label="'取消选择 '+o.name" @click.stop="toggleLayer(o)">✓</button><component :is="group.icon" :size="15"/><input v-if="renamingLayer===o.id" v-model="layerNameDraft" :data-rename-layer="o.id" aria-label="重命名图层" maxlength="120" @click.stop @keydown.enter.stop.prevent="saveLayerName(o)" @keydown.esc.stop="renamingLayer=null" @blur="saveLayerName(o)"/><span v-else>{{o.name}}</span><button class="icon-button layer-rename" :title="'重命名 '+o.name" :aria-label="'重命名 '+o.name" @click.stop="renameLayer(o)"><Pencil :size="13"/></button><Link v-if="o.linkGroup" :size="13" class="bubble-chain"/><button class="icon-button" :aria-label="'显示或隐藏 '+o.name" @click.stop="checkpoint();o.visible=o.visible===false"><EyeOff v-if="o.visible===false" :size="13"/><Eye v-else :size="13"/></button></div></template></template></div></section>
  <section class="card object-properties"><div class="card-heading"><strong>{{s.t('对象属性','Properties')}}</strong><span>{{selected==='cutout-group'?'抠图图层组':object?.name||s.t('主画布','Page')}}</span></div><div class="property-body" @parameter-edit-start="checkpoint"><template v-if="selected==='canvas'"><label>{{s.t('画布宽度','Page width')}}<input type="number" :value="page.width" @change="editPageSize('width',Number($event.target.value))" min="256" max="8192"/></label><label>{{s.t('画布高度','Page height')}}<input type="number" :value="page.height" @change="editPageSize('height',Number($event.target.value))" min="256" max="8192"/></label><label class="inline-check"><input type="checkbox" v-model="page.keepCanvasRatio"/>按比例修改画布尺寸</label><label class="inline-check"><input type="checkbox" v-model="page.scaleCanvasContents"/>所有画面跟随画布缩放</label><label>{{s.t('背景颜色','Background color')}}<input type="color" v-model="page.background"/></label><button class="secondary" @click="backgroundInput.click()">{{s.t('更换背景图片','Change background image')}}</button><button v-if="page.backgroundImage" class="quiet" @click="page.backgroundImage=null">{{s.t('移除背景图片','Remove background')}}</button></template>
   <template v-else-if="selected==='cutout-group'"><label class="inline-check"><input type="checkbox" :checked="page.cutoutsVisible!==false" @change="page.cutoutsVisible=$event.target.checked"/>显示整个抠图图层组</label><label>图层组不透明度<input type="range" :value="page.cutoutOpacity??1" @input="page.cutoutOpacity=Number($event.target.value)" min="0" max="1" step=".01"/></label><p class="muted">选择组内的主体图层，可单独调整位置、缩放、旋转和不透明度。</p></template><template v-else-if="object"><label>{{s.t('图层名称','Layer name')}}<input v-model="object.name"/></label><div v-if="object.kind!=='stroke'" class="property-grid"><label v-for="(label,key) in {x:'X',y:'Y',w:s.t('宽度','Width'),h:s.t('高度','Height')}" :key="key">{{label}}<input type="number" :value="Math.round(selectedBounds[key])" @focus="checkpoint()" @input="$event.target.value!==''&&updateGeometry(key,Number($event.target.value))"/></label></div><label v-if="object.kind!=='stroke'">{{s.t('旋转角度','Rotation')}}<input type="number" v-model.number="object.rotation" :disabled="!!object.linkGroup" min="-180" max="180"/></label>
    <template v-if="panel"><label>分镜边数<NumberControl :model-value="panel.points.length" :min="3" :max="32" label="分镜边数" unit="边" @update:model-value="changePanelSides"/></label><p class="muted panel-sides-hint">支持 3–32 边，顶点可在画布中拖动；更改边数会重排形状，可撤销。</p><div class="panel-actions"><button class="primary" @click="generatePanel()"><Sparkles :size="15"/>{{s.t('为这个分镜生成图像','Generate for this panel')}}</button><button class="secondary" @click="fileInput.click()"><Upload :size="15"/>{{s.t('上传图像','Import image')}}</button><button class="secondary" @click="galleryOpen=true"><Images :size="15"/>{{s.t('从画廊选择','Choose from gallery')}}</button></div><template v-if="panel.image"><button class="secondary" @click="openImageEditor(panel)">取景 / 智能抠图 / 破框</button><label>{{s.t('图片缩放','Image zoom')}}<input type="range" v-model.number="panel.imageScale" min="0.3" max="4" step="0.05"/></label><div class="property-grid"><label>{{s.t('图片左右移动','Image horizontal')}}<input type="number" v-model.number="panel.imageX"/></label><label>{{s.t('图片上下移动','Image vertical')}}<input type="number" v-model.number="panel.imageY"/></label></div><button class="quiet" @click="checkpoint();panel.image=null;panel.imageId=null">{{s.t('移除分镜图像','Remove image')}}</button></template><div class="property-grid"><label>{{s.t('边框颜色','Border color')}}<input type="color" v-model="panel.border"/></label><label>{{s.t('边框粗细','Border width')}}<input type="number" v-model.number="panel.borderWidth" min="0" max="30"/></label></div></template>
    <template v-if="object.cutout"><label class="inline-check"><input type="checkbox" :checked="object.hidePanelBorder!==false" @change="object.hidePanelBorder=$event.target.checked"/>自动隐藏主体下方的分镜边框</label><label class="inline-check"><input type="checkbox" v-model="object.outsideOnly"/>只显示框外主体（框内保持原画）</label><label>主体缩放<input type="range" :value="object.w/(object.cutoutBaseW||object.w)" @input="scaleCutout(Number($event.target.value))" min=".1" max="5" step=".02"/></label><label>不透明度<input type="range" :value="object.opacity??1" @input="object.opacity=Number($event.target.value)" min="0" max="1" step=".01"/></label><button class="secondary align-source-button" @click="alignCutout">自动对齐原图</button><button class="secondary" @click="refineCutout()">重新识别 / 修边</button></template><template v-if="['text','bubble','sticker'].includes(object.kind)&&!object.cutout"><button class="secondary" @click="editDecoration">{{object.kind==='sticker'?'更换贴纸':'选择形状 / 样式'}}</button><template v-if="object.kind!=='sticker'||(!object.presetId&&!object.image)"><TextFormatting :model="object"/><label>{{s.t('内容（换行分段）','Content (newline supported)')}}<textarea v-model="object.text" rows="4"/></label><label>{{s.t('字号','Font size')}}<input type="number" v-model.number="object.fontSize" min="8" max="200"/></label><label>{{s.t('文字颜色','Text color')}}<input type="color" v-model="object.color"/></label></template><label v-if="object.kind==='sticker'">贴纸颜色<input type="color" v-model="object.color"/></label><label v-if="object.kind==='bubble'">{{s.t('对白背景','Bubble fill')}}<input type="color" v-model="object.fill"/></label><template v-if="object.kind==='bubble'"><template v-if="object.linkGroup"><label>粘连幅度<input type="range" v-model.number="page.bubbleLinks[object.linkGroup].strength" min="0" max="1" step=".01"/></label><button class="secondary" @click="unlinkBubbles"><Unlink :size="14"/>解除对白粘连</button></template><label>对话框形状<select v-model="object.shape"><option v-for="p in bubblePresets" :value="p.id">{{p.name}}</option></select></label><label class="inline-check"><input type="checkbox" :checked="object.tailEnabled!==false" @change="object.tailEnabled=$event.target.checked"/>显示尾巴</label><template v-if="object.tailEnabled!==false"><label>尾巴角度（0°向右，90°向下）<input type="number" :value="object.tailAngle??135" @input="object.tailAngle=Number($event.target.value)"/></label><label>尾巴长度<input type="range" :value="object.tailLength??.5" @input="object.tailLength=Number($event.target.value)" min=".05" max="3" step=".05"/></label><label>尾巴宽度<input type="range" :value="object.tailWidth??24" @input="object.tailWidth=Number($event.target.value)" min="8" max="70"/></label></template><label>边框粗细<input type="number" v-model.number="object.borderWidth" min="0" max="20"/></label></template><button v-if="object.kind==='sticker'" class="secondary" @click="saveSticker">保存到我的贴纸</button></template><template v-if="object.kind==='stroke'"><label>{{s.t('笔画颜色','Stroke color')}}<input type="color" v-model="object.color"/></label><label>{{s.t('笔画粗细','Stroke width')}}<input type="number" v-model.number="object.width" min="1" max="100"/></label></template>
   </template><div v-if="tool==='brush'||tool==='eraser'" class="brush-settings"><label>{{s.t('画笔粗细','Brush width')}}<input type="range" v-model.number="brushSize" min="1" max="60"/></label><label>{{s.t('画笔颜色','Brush color')}}<input type="color" v-model="brushColor"/></label></div></div></section>
 </aside></div><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" class="hidden" @change="uploadImage"/><input ref="projectInput" type="file" accept=".json" class="hidden" @change="importProject"/>
 <div v-if="panelGenerator&&generatingPanel" class="modal-backdrop" @click.self="s.action(closePanelGenerator)"><section class="modal panel-generation-modal" role="dialog" :aria-label="panelGenerator.mode==='inpaint'?'为分镜重绘图像':'为分镜生成图像'"><div class="modal-dismiss-row"><button class="icon-button" aria-label="关闭分镜生成面板" @click="panelGenerator=null"><X/></button></div><div class="modal-title"><div><h2>{{panelGenerator.mode==='inpaint'?'为分镜重绘图像':'为分镜生成图像'}} · {{generatingPanel.name}}</h2><p>项目第 {{s.project.pages.findIndex(pg=>pg.id===panelGenerator.pageId)+1}} 页 · 此分镜独立保存提示词和参数，生成后自动回填。</p></div></div><div class="panel-generation-columns" v-resize-panels="{key:'panel-generator',config:s.config,min:[440,180],labels:['调整候选图片列宽度']}"><Generation :key="panelGenerator.panelId+':'+panelGenerator.mode" :mode="panelGenerator.mode" embedded :panel-target="panelGenerator" :panel="generatingPanel" :page="s.project.pages.find(pg=>pg.id===panelGenerator.pageId)" @queued="panelGroup=$event.groupId"/><aside class="panel-candidates" aria-label="当前分镜候选图片"><div class="panel-candidates-heading"><strong>图片候选</strong><span>{{candidates.length}} 张</span></div><p class="muted">点击候选图填入当前分镜，同时载入它的提示词和参数。</p><div class="panel-candidate-list"><button v-for="(item,index) in candidates" :key="item.id||item.url" :aria-label="'选择分镜候选图 '+(index+1)" :aria-pressed="(generatingPanel.imageId===item.id||generatingPanel.image===item.url)" :class="['panel-candidate',{selected:(generatingPanel.imageId===item.id||generatingPanel.image===item.url)}]" @click="chooseCandidate(item)"><img :src="item.url" :alt="'候选图 '+(index+1)" loading="lazy"/><span>{{(generatingPanel.imageId===item.id||generatingPanel.image===item.url)?'正在使用':'点击填入'}} · {{item.params?.seed||'导入图片'}}</span></button><p v-if="!candidates.length" class="empty">生成的图片会显示在这里，连续生成的结果都会保留。</p></div></aside></div></section></div><CutoutEditor v-if="cutoutRefine" :image="cutoutRefine.source.url" :image-id="cutoutRefine.source.id" :page="page" :panel="cutoutRefine.panel||layerSourcePanel(cutoutRefine.object,page)" :cutout="cutoutRefine.object" :initial-result="cutoutRefine.object?{id:cutoutRefine.object.imageId,url:cutoutRefine.object.image}:null" @close="cutoutRefine=null" @done="finishCutoutRefine"/><PanelImageEditor v-if="panelImageEditor" :panel="panelImageEditor" :page="page" @close="panelImageEditor=null" @cutout="addCutout"/><input ref="cutoutInput" class="hidden" type="file" accept="image/png,image/jpeg,image/webp" multiple @change="importCutout"/><input ref="backgroundInput" class="hidden" type="file" accept="image/png,image/jpeg,image/webp" @change="changeBackground"/><DecorationPicker v-if="picker" :kind="picker.kind" :initial="picker.initial" @close="picker=null" @choose="applyDecoration"/><Teleport to="body"><template v-if="bubbleMenu"><div class="layer-context-dismiss" @pointerdown="bubbleMenu=null" @contextmenu.prevent="bubbleMenu=null"/><div class="bubble-context-menu" role="menu" aria-label="图层右键菜单" :style="{left:bubbleMenu.x+'px',top:bubbleMenu.y+'px'}"><div class="layer-order-menu"><button role="menuitem" :disabled="!canReorder(1)" title="在同组内上移" @click="reorderSelection(1)"><ArrowUp :size="13"/>上移</button><button role="menuitem" :disabled="!canReorder(-1)" title="在同组内下移" @click="reorderSelection(-1)"><ArrowDown :size="13"/>下移</button><button role="menuitem" :disabled="!canReorder(1,'all')" title="向前调整遮挡顺序，可跨图层组" @click="reorderSelection(1,'all')"><Layers :size="13"/>图层上移</button><button role="menuitem" :disabled="!canReorder(-1,'all')" title="向后调整遮挡顺序，可跨图层组" @click="reorderSelection(-1,'all')"><Layers :size="13"/>图层下移</button></div><div class="layer-menu-divider"/><button role="menuitem" class="danger" :disabled="!bubbleSelection.length" @click="deleteSelectedLayers"><Trash2 :size="15"/>删除</button><template v-if="selectedBubbles.length>=2"><button role="menuitem" @click="linkBubbles"><Link :size="15"/>粘连</button><button role="menuitem" @click="unlinkBubbles"><Unlink :size="15"/>取消粘连</button></template></div></template></Teleport><div v-if="galleryOpen" class="modal-backdrop" @click.self="galleryOpen=false"><section class="modal"><div class="modal-dismiss-row"><button class="icon-button" @click="galleryOpen=false"><X/></button></div><div class="modal-title"><h2>{{s.t('选择分镜图像','Choose a panel image')}}</h2></div><div class="picker-grid"><button v-for="item in s.gallery" @click="placeImage(item)"><img :src="item.url"/><span>{{item.title}}</span></button></div><p v-if="!s.gallery.length" class="empty">{{s.t('先生成或导入一张图片','Generate or import an image first')}}</p></section></div>
 <div v-if="confirmAction" class="modal-backdrop" @click.self="confirmAction=null"><section class="modal confirm-modal"><div class="modal-dismiss-row"><button class="icon-button" aria-label="关闭操作确认" @click="confirmAction=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{s.t('确认操作','Confirm')}}</h2></div><p>{{confirmAction.text}}</p><div class="button-row"><button class="secondary" @click="confirmAction=null">{{s.t('取消','Cancel')}}</button><button class="primary" @click="confirmAction.run();confirmAction=null">{{s.t('确认','Confirm')}}</button></div></section></div>
 <ProjectBrowser v-if="projectDialog" @close="projectDialog=false"/>
</div></template>
